    '這一版不需要看方塊。系統會讀出經文出處，停頓，然後用語音引導你背誦。請允許麥克風，照著提示開口唸出經文。': 'در این نسخه نیازی به نگاه کردن به مربع ها نیست. سیستم منبع کتاب مقدس را می خواند، مکث می کند و سپس از صدا برای راهنمایی شما برای خواندن آن استفاده می کند. لطفاً به میکروفون اجازه دهید و دستورات را دنبال کنید تا متن مقدس را بخوانید.',
