    '（在此裝置上未找到經文文字，但仍可雙擊挑戰）': '(متن کتاب مقدس در این دستگاه یافت نشد، اما همچنان می توان با دوبار کلیک کردن آن را به چالش کشید)',
    ' 個果子，達到 Lv.2 即可解鎖個人專屬連結！': 'میوه ها، به Lv.2 برسید تا یک پیوند انحصاری شخصی را باز کنید!',
    '6位數驗證碼': 'کد تایید 6 رقمی',
    '<strong>提示：</strong> 魔法一鍵抓取功能串接了精準的華語聖經資料庫，能夠大幅省去手動打字、校稿的時間。您可以直接嘗試輸入「創世紀 1:1」，感受一秒匯入的流暢度！': '<strong>نکته:</strong> عملکرد جادویی ضبط با یک کلیک به پایگاه داده دقیق کتاب مقدس چینی متصل است، که می تواند تا حد زیادی در زمان تایپ دستی و تصحیح کتاب صرفه جویی کند. می توانید مستقیماً سعی کنید وارد "پیدایش 1: 1" شوید و روان بودن واردات را در یک ثانیه تجربه کنید!',
