    '當你分享的邀請連結帶來新玩家，或你創作了廣受歡迎的自訂經文組，系統會自動為你累積推廣點數。': 'هنگامی که پیوند دعوتی که به اشتراک می گذارید، بازیکنان جدیدی می آورد، یا یک بانک سؤال سفارشی محبوب ایجاد می کنید، سیستم به طور خودکار امتیازهای تبلیغاتی را برای شما جمع می کند.',
