    '線上排行榜能激勵會眾、青年團契和小組成員一起參與遊玩、共同精進！': 'Bảng xếp hạng trực tuyến có thể khuyến khích các hội thánh, nhóm thanh niên và thành viên nhóm tham gia vui chơi và cùng nhau tiến bộ!',
