    '總果子': 'tổng số trái cây',
    '聆聽': 'Nghe',
    '聖經經文的單字會從天而降，玩家只要按照正確的順序點擊經文就能獲得分數。經文被點擊時，會用語音朗讀出來，從視覺和語音的聽覺兩方面來加強您的記憶。': 'Các từ trong các câu Kinh thánh sẽ từ trên trời rơi xuống và người chơi có thể kiếm điểm bằng cách nhấp vào các câu theo đúng thứ tự. Khi các câu thơ được nhấp vào, chúng sẽ được đọc to bằng giọng nói, nâng cao trí nhớ của bạn thông qua cả khía cạnh thính giác và hình ảnh.',
    '聯絡與建議': 'Liên hệ và tư vấn',
