    '視障版開始。請允許麥克風。聽到提示音後，開口背誦經文。': 'Phiên bản dành cho người khiếm thị bắt đầu. Vui lòng cho phép micrô. Sau khi nghe tiếng bíp, hãy đọc kinh.',
