    '你完成了所有經文！': 'Bạn đã hoàn thành tất cả các câu thơ!',
    '你的專屬推廣連結：當朋友們透過此連結直接進入加入 VerseRain，並完成他們的第一次背經遊戲，雙方都會自動獲得「推廣點數」獎勵，同時你也將累積推廣大使進度！': 'Liên kết khuyến mãi độc quyền của bạn: Khi bạn bè tham gia VerseRain trực tiếp thông qua liên kết này và hoàn thành trò chơi ghi nhớ đầu tiên của họ, cả hai bên sẽ tự động nhận được phần thưởng "điểm khuyến mãi" và bạn cũng sẽ tích lũy tiến độ đại sứ khuyến mãi!',
    '你的暱稱': 'biệt danh của bạn',
