    '你目前還沒有權限建立專屬經文組。有兩種方式可以解鎖：': 'Hiện tại bạn chưa có quyền tạo bộ câu Kinh Thánh riêng. Có hai cách để mở khóa:',
    '你還沒有建立任何專屬經文組。點擊上方按鈕開始！': 'Bạn chưa tạo bộ câu Kinh Thánh riêng nào. Nhấp vào nút ở trên để bắt đầu!',
