    '你的專屬推廣連結：當朋友們透過此連結直接進入加入 VerseRain，並完成他們的第一次背經遊戲，雙方都會自動獲得「推廣點數」獎勵，同時你也將累積推廣大使進度！': 'သင်၏သီးသန့် ပရိုမိုးရှင်းလင့်ခ်- သူငယ်ချင်းများသည် VerseRain လင့်ခ်မှတစ်ဆင့် တိုက်ရိုက်ဝင်ရောက်ပြီး ၎င်းတို့၏ ပထမဆုံး အလွတ်ကျက်ဂိမ်းကို ပြီးမြောက်သောအခါ၊ နှစ်ဦးနှစ်ဘက်စလုံးသည် "ပရိုမိုးရှင်းအမှတ်များ" ဆုလာဘ်များကို အလိုအလျောက်ရရှိမည်ဖြစ်ပြီး၊ သင်သည် ပရိုမိုးရှင်းသံတမန်တိုးတက်မှုကိုလည်း စုဆောင်းရရှိမည်ဖြစ်သည်။',
