    '在左上角確認一切無誤後，點擊 <strong>「發佈 (Publish)」</strong>。': 'ဘယ်ဘက်အပေါ်ထောင့်မှာ အရာအားလုံးမှန်ကန်ကြောင်း အတည်ပြုပြီးတာနဲ့၊ <strong>Publish</strong> ကိုနှိပ်ပါ။',
