    '想要將神聖高分刻在群組榜單上嗎？': 'သင်၏မြင့်မြတ်သောရမှတ်ကို အုပ်စုခေါင်းဆောင်စာရင်းတွင် ထည့်သွင်းလိုပါသလား။',
    '想要擁有你的個人推薦碼並賺取推廣點數嗎？': 'သင့်ကိုယ်ပိုင် ရည်ညွှန်းကုဒ်ကို ပိုင်ဆိုင်ပြီး ပရိုမိုးရှင်းအမှတ်များ ရယူလိုပါသလား။',
