    '房主可以從全域經文組中挑選 <strong>「比賽經文」</strong>。': 'အခန်းပိုင်ရှင်သည် ကမ္ဘာလုံးဆိုင်ရာကျမ်းချက်စုများမှ <strong>"ပြိုင်ပွဲကျမ်းချက်များ"</strong> ကို ရွေးချယ်နိုင်ပါသည်။',
