    "選擇你喜歡的語音，首頁「讀經」及遊戲中的語音都會使用此設定。": "Escolha a voz de sua preferência. Ela será usada tanto na \"Leitura da Bíblia\" da página inicial quanto no jogo.",
    "系統預設語音": "Voz padrão do sistema",
