    "這是你選擇的語音試聽。": "Esta é a amostra da voz escolhida.",
    "已記住你的語音偏好，下次回來會自動使用。": "Sua preferência de voz foi salva e será usada automaticamente na próxima vez.",
    "團隊競賽": "Competição por equipes",
    "經文庫": "Biblioteca de versículos",
    "經題萬卷勤溫故，句句生光照此程。": "Explore conjuntos globais de versículos e escolha passagens para praticar.",
    "同心競走天路程，並肩得勝主名榮。": "Crie uma sala, formem equipes e desafiem versículos juntos.",
    "老師先選擇隊伍數量，再建立房間。學生加入一個聖靈果子隊伍，最後用隊伍平均分排名。": "O professor escolhe primeiro o número de equipes e depois cria a sala. Os alunos entram numa equipe do Fruto do Espírito, e a classificação final é ordenada pela média da equipe.",
