    "這一版不需要看方塊。系統會讀出經文出處，停頓，然後用語音引導你背誦。請允許麥克風，照著提示開口唸出經文。": "Dans cette version, pas besoin de regarder les blocs. Le système lit la référence, marque une pause, puis vous guide vocalement pour la réciter. Autorisez le microphone et suivez les instructions pour lire le verset.",
