    "<strong>提示：</strong> 魔法一鍵抓取功能串接了精準的華語聖經資料庫，能夠大幅省去手動打字、校稿的時間。您可以直接嘗試輸入「創世紀 1:1」，感受一秒匯入的流暢度！": "<strong>Astuce :</strong> la fonction magique de capture en un clic est reliée à une base biblique précise, ce qui fait gagner beaucoup de temps de saisie et de relecture. Essayez « Genèse 1:1 » et découvrez la fluidité d’une importation en une seconde !",
