    "你的專屬推廣連結：當朋友們透過此連結直接進入加入 VerseRain，並完成他們的第一次背經遊戲，雙方都會自動獲得「推廣點數」獎勵，同時你也將累積推廣大使進度！": "Votre lien de promotion exclusif : lorsque des amis rejoignent VerseRain directement via ce lien et terminent leur premier jeu de mémorisation, vous recevez tous deux automatiquement des « points de promotion », et vous progressez en tant qu’ambassadeur !",
