    "關閉視障經文雨": "Выключить доступный дождь стихов",
    "打開視障經文雨": "Включить доступный дождь стихов",
    "為視覺障礙朋友設計的語音模式": "Голосовой режим для незрячих",
    "關閉效能模式": "Выключить режим производительности",
    "打開效能模式": "Включить режим производительности",
    "關閉華麗特效以提升流暢度": "Отключает красивые эффекты для плавности",
    "關閉 Debug": "Выключить отладку",
    "打開 Debug": "Включить отладку",
    "顯示除錯資訊": "Показывать отладочную информацию",
    "朗讀語音設定": "Настройка голоса чтения",
    "選擇你喜歡的語音，首頁「讀經」及遊戲中的語音都會使用此設定。": "Выберите любимый голос. Он будет использоваться и для «Чтения Библии» на главной, и для озвучки в игре.",
    "系統預設語音": "Голос системы по умолчанию",
    "試聽": "Прослушать",
    "語音已更新！": "Голос обновлён!",
    "這是你選擇的語音試聽。": "Это прослушивание выбранного голоса.",
    "已記住你的語音偏好，下次回來會自動使用。": "Ваши настройки голоса сохранены и будут использованы автоматически в следующий раз.",
    "團隊競賽": "Командное соревнование",
    "經文庫": "Библиотека стихов",
    "經題萬卷勤溫故，句句生光照此程。": "Исследуйте мировые наборы стихов и выбирайте отрывки для практики.",
    "同心競走天路程，並肩得勝主名榮。": "Создайте комнату, соберите команды и проходите стихи вместе.",
    "老師先選擇隊伍數量，再建立房間。學生加入一個聖靈果子隊伍，最後用隊伍平均分排名。": "Учитель сначала выбирает число команд, затем создаёт комнату. Ученики вступают в команду Плода Духа, а итоговый рейтинг строится по среднему баллу команды.",
