    "{name}，今日的經文雨活動已累積 {n} 分": "{name}, hoy has acumulado {n} puntos en la actividad de VerseRain",
    "今日的經文雨活動已累積 {n} 分": "Hoy has acumulado {n} puntos en la actividad de VerseRain",
    "連續 {n} 天": "Racha de {n} días",
    "今天開始建立連續紀錄吧！": "¡Empieza tu racha hoy!",
    "最長連續：{n} 天": "Mejor: {n} días",
    "個人累積": "Acumulado",
    "已挑戰": "Partidas",
    "已栽種": "Árboles",
    "結果子": "Con fruto",
    "前往這個經文組": "Ir a este conjunto de versículos",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Lee en voz alta con tu propia voz",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Mientras <strong>escuchas un conjunto de versículos</strong>, puedes grabar tu propia voz leyendo un versículo. La próxima vez que lo reproduzcas te oirás a ti en vez de la voz del ordenador — y puedes compartirlo para que tus amigos también te oigan.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Graba tu voz:</strong> (requiere iniciar sesión) En la fila de botones al pie de la pantalla de escucha, toca el 🎙️ micrófono, lee el versículo en voz alta y guarda.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Prioridad de reproducción:</strong> tu voz ＞ la voz del autor del conjunto ＞ voz del ordenador (TTS). Una vez que grabas, siempre te oirás a ti.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Mejorar voz:</strong> Tras grabar puedes activar «Mejorar voz» para más claridad. El procesado y la subida ocurren <strong>en segundo plano</strong> (se muestra «⏳ Procesando…»), así que puedes grabar el siguiente versículo de inmediato.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Comparte tu voz:</strong> Toca el botón 🔗 compartir y tu amigo oirá tu voz al abrir el enlace. Si la grabación aún se sube, el botón espera a que termine para que siempre la oiga.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Pausar / Reanudar:</strong> Al reproducir una grabación de voz, Pausar mantiene la posición y Reanudar <strong>continúa desde donde se detuvo</strong> en lugar de empezar de nuevo.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Eliminar:</strong> Si bajo la referencia aparece «🎙️ Tu voz en este versículo», toca «Eliminar ✕» al lado para quitar tu grabación; luego se usará la voz del autor o del ordenador.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Consejo:</strong> El botón en el centro superior de la pantalla de escucha (que muestra la fecha o el nombre del tema) tiene debajo <strong>[Más versículos temáticos]</strong> — tócalo para abrir más conjuntos temáticos y cambiar rápido.",
