    "這是視障友善版。現在選擇的是 {title}，本次 {n} 節經文。按開始後，系統會先讀經文出處，停頓兩秒，再等你開口背誦。若一段時間沒有答對，系統會朗讀提示。遊戲中按 Escape 可以離開。": "Dies ist der barrierefreie Modus. Das gewählte Set ist {title}, {n} Verse. Nach dem Start liest die App die Referenz, pausiert zwei Sekunden und wartet auf dein Aufsagen. Wenn du Hilfe brauchst, liest die App einen Hinweis. Drücke während des Spiels Escape zum Verlassen.",
