    "這節之前是用別的帳號錄的,無法覆蓋。請先刪掉這一行再重加,或用原本的帳號登入。": "Dieser Vers wurde mit einem anderen Konto aufgenommen und kann nicht überschrieben werden. Entferne diese Zeile und füge sie neu hinzu, oder melde dich mit dem ursprünglichen Konto an.",
