    "今日的經文雨活動已累積 {n} 分": "Du hast heute {n} Punkte bei der VerseRain-Aktivität gesammelt",
    "連續 {n} 天": "{n}-Tage-Serie",
    "今天開始建立連續紀錄吧！": "Starte heute deine Serie!",
    "最長連續：{n} 天": "Bestwert: {n} Tage",
    "個人累積": "Gesamt",
    "已挑戰": "Runden",
    "已栽種": "Bäume",
    "結果子": "Frucht getragen",
    "前往這個經文組": "Zu diesem Versset gehen",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Lies laut mit deiner eigenen Stimme",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Während du <strong>ein Versset anhörst</strong>, kannst du deine eigene Stimme aufnehmen, wie du einen Vers liest. Beim nächsten Mal hörst du dich selbst statt der Computerstimme — und du kannst es teilen, damit Freunde auch deine Stimme hören.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Nimm deine Stimme auf:</strong> (Anmeldung nötig) In der Buttonreihe unten im Hörbildschirm tippe auf das 🎙️ Mikrofon, lies den Vers laut und speichere.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Wiedergabe-Priorität:</strong> deine Stimme ＞ die Stimme des Set-Autors ＞ Computerstimme (TTS). Sobald du aufgenommen hast, hörst du immer dich selbst.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Stimme verbessern:</strong> Nach der Aufnahme kannst du „Stimme verbessern“ für mehr Klarheit aktivieren. Verarbeitung und Upload laufen <strong>im Hintergrund</strong> (angezeigt als „⏳ Verarbeitung…“), du kannst also gleich den nächsten Vers aufnehmen.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Teile deine Stimme:</strong> Tippe auf den 🔗 Teilen-Button, und dein Freund hört deine Stimme, wenn er den Link öffnet. Läuft die Aufnahme noch, wartet der Button, bis sie fertig ist, damit er sie immer hört.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Pause / Fortsetzen:</strong> Beim Abspielen einer Sprachaufnahme hält Pause die Position, und Fortsetzen <strong>macht dort weiter, wo es gestoppt hat</strong>, statt neu zu beginnen.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Löschen:</strong> Wenn unter der Referenz „🎙️ Deine Stimme bei diesem Vers“ steht, tippe daneben auf „Löschen ✕“, um deine Aufnahme zu entfernen; die Wiedergabe fällt dann auf die Autoren- oder Computerstimme zurück.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Tipp:</strong> Der Button oben in der Mitte des Hörbildschirms (mit Datum oder Themennamen) hat darunter <strong>[Mehr thematische Verse]</strong> — tippe darauf, um mehr Themen-Verssets zu öffnen und schnell zu wechseln.",
