    "前往這個經文組": "Bu ayet setine git",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Kendi Sesinle Sesli Oku",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Bir <strong>ayet setini dinlerken</strong> bir ayeti okurken kendi sesini kaydedebilirsin. O ayeti bir dahaki oynatışında bilgisayar sesi yerine kendini duyarsın — ve arkadaşların da sesini duysun diye paylaşabilirsin.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Sesini kaydet:</strong> (giriş gerekli) Dinleme ekranının altındaki düğme sırasında 🎙️ mikrofona dokun, ayeti sesli oku ve kaydet.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Oynatma önceliği:</strong> senin sesin ＞ set yazarının sesi ＞ bilgisayar sesi (TTS). Kaydettiğinde hep kendini duyarsın.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Sesi iyileştir:</strong> Kayıttan sonra netlik için \"Sesi iyileştir\"i açabilirsin. İşleme ve yükleme <strong>arka planda</strong> çalışır (\"⏳ İşleniyor…\" görünür), böylece hemen sonraki ayeti kaydedebilirsin.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Sesini paylaş:</strong> 🔗 paylaş düğmesine dokun; arkadaşın bağlantıyı açınca sesini duyar. Kayıt hâlâ yükleniyorsa, düğme bitmesini bekler ki hep duyabilsin.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Duraklat / Devam:</strong> Bir ses kaydı çalarken Duraklat konumu tutar, Devam ise baştan başlamak yerine <strong>kaldığı yerden sürdürür</strong>.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Sil:</strong> Referansın altında \"🎙️ Bu ayette senin sesin\" yazıyorsa, kaydını kaldırmak için yanındaki \"Sil ✕\"e dokun; oynatma sonra yazarın ya da bilgisayarın sesine döner.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>İpucu:</strong> Dinleme ekranının üst ortasındaki düğmenin (tarih ya da konu adını gösterir) altında <strong>[Daha fazla konu ayeti]</strong> yazar — daha fazla konu seti açıp hızlıca geçmek için ona dokun.",
