    "結果子": "میوه داد",
    "前往這個經文組": "رفتن به این مجموعهٔ آیه",
    "五、親聲朗讀 — 用你自己的聲音讀經": "۵. با صدای خودتان بلند بخوانید",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "هنگام <strong>شنیدن یک مجموعهٔ آیه</strong>، می‌توانید صدای خودتان را در خواندن یک آیه ضبط کنید. دفعهٔ بعد که آن آیه را پخش کنید، به‌جای صدای رایانه صدای خودتان را می‌شنوید — و می‌توانید آن را به اشتراک بگذارید تا دوستان هم صدای شما را بشنوند.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>صدای خود را ضبط کنید:</strong> (نیاز به ورود) در ردیف دکمه‌های پایین صفحهٔ شنیدن، روی میکروفون 🎙️ بزنید، آیه را بلند بخوانید و ذخیره کنید.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>اولویت پخش:</strong> صدای شما ＞ صدای نویسندهٔ مجموعه ＞ صدای رایانه (TTS). پس از ضبط، همیشه صدای خودتان را می‌شنوید.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ بهبود صدا:</strong> پس از ضبط می‌توانید «بهبود صدا» را برای وضوح بیشتر روشن کنید. پردازش و بارگذاری <strong>در پس‌زمینه</strong> انجام می‌شود («⏳ در حال پردازش…» نمایش داده می‌شود)، پس می‌توانید بی‌درنگ آیهٔ بعدی را ضبط کنید.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>صدای خود را به اشتراک بگذارید:</strong> روی دکمهٔ اشتراک 🔗 بزنید و دوست شما با باز کردن لینک صدای شما را می‌شنود. اگر ضبط هنوز در حال بارگذاری است، دکمه تا پایان صبر می‌کند تا او همیشه بشنود.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>مکث / ادامه:</strong> هنگام پخش ضبط صوتی، مکث موقعیت را نگه می‌دارد و ادامه به‌جای شروع از ابتدا <strong>از همان‌جا که متوقف شد ادامه می‌دهد</strong>.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>حذف:</strong> اگر زیر نشانی «🎙️ صدای شما روی این آیه» نمایش داده شد، برای حذف ضبط خود روی «حذف ✕» کنارش بزنید؛ سپس پخش به صدای نویسنده یا رایانه بازمی‌گردد.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>نکته:</strong> زیر دکمهٔ وسط بالای صفحهٔ شنیدن (که تاریخ یا نام موضوع را نشان می‌دهد) نوشته شده <strong>[آیات موضوعی بیشتر]</strong>؛ با زدن آن مجموعه‌های موضوعی بیشتری باز می‌شود و سریع می‌توانید جابه‌جا شوید.",
    "多人遊戲進行中": "چندنفره در حال اجرا",
