    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>סדר עדיפות בנגינה:</strong> הקול שלך ＞ קול מחבר הסט ＞ קול מחשב (TTS). לאחר שהקלטת, תמיד תשמע את עצמך.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ שיפור קול:</strong> לאחר ההקלטה אפשר להפעיל \"שיפור קול\" לבהירות. העיבוד וההעלאה מתבצעים <strong>ברקע</strong> (מוצג \"⏳ מעבד…\"), כך שאפשר מיד להקליט את הפסוק הבא.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>שתף את קולך:</strong> הקש על כפתור השיתוף 🔗 והחבר ישמע את קולך כשיפתח את הקישור. אם ההקלטה עדיין עולה, הכפתור ממתין לסיום כדי שתמיד יישמע.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>השהיה / המשך:</strong> בעת נגינת הקלטת קול, השהיה שומרת על המיקום והמשך <strong>ממשיך מהנקודה שבה נעצר</strong> במקום להתחיל מחדש.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>מחיקה:</strong> אם מתחת למראה מקום מופיע \"🎙️ הקול שלך על פסוק זה\", הקש על \"מחק ✕\" שלצדו כדי להסיר את ההקלטה; לאחר מכן הנגינה חוזרת לקול המחבר או המחשב.",
