    "這是視障友善版。現在選擇的是 {title}，本次 {n} 節經文。按開始後，系統會先讀經文出處，停頓兩秒，再等你開口背誦。若一段時間沒有答對，系統會朗讀提示。遊戲中按 Escape 可以離開。": "これはアクセシブルモードです。選択中のセットは{title}、{n}節です。開始すると参照を読み上げ、2秒待ってからあなたの暗唱を待ちます。困ったらヒントを読み上げます。ゲーム中にEscapeで退出できます。",
