    "你是主持人並一起參賽 — 請先選一個隊伍，再按「比賽開始」": "あなたはホストで参加します — 先にチームを選び、「開始」を押してください",
    "你是主持人並一起參賽，準備好就按「比賽開始」": "あなたはホストで参加します — 準備ができたら「開始」を押してください",
