    "這節有人聲錄音": "この節に音声録音があります",
    "有人聲錄音": "音声録音あり",
    "分享聆聽連結": "再生リンクを共有",
    "今日問候": "今日のあいさつ",
    "{name}，今日的經文雨活動已累積 {n} 分": "{name}さん、今日の経文雨アクティビティで{n}点たまりました",
    "今日的經文雨活動已累積 {n} 分": "今日の経文雨アクティビティで{n}点たまりました",
    "連續 {n} 天": "{n}日連続",
    "今天開始建立連續紀錄吧！": "今日から連続記録を始めよう！",
    "最長連續：{n} 天": "最長：{n}日",
    "個人累積": "累計",
    "已挑戰": "プレイ数",
    "已栽種": "木",
    "結果子": "実を結んだ",
    "前往這個經文組": "この聖句セットへ",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. 自分の声で音読する",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "<strong>聖句セットを聴いている</strong>とき、ある節を読む自分の声を録音できます。次にその節を再生すると、コンピューター音声ではなく自分の声が聞こえ、友だちにも共有して聞いてもらえます。",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>あなたの声を録音：</strong>（要ログイン）聴く画面の下のボタン列にある🎙️マイクをタップし、節を音読して保存します。",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>再生の優先順位：</strong>あなたの声 ＞ セット作者の声 ＞ コンピューター音声（TTS）。一度録音すれば常に自分の声が聞こえます。",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ 音声補正：</strong>録音後に「音声補正」をオンにすると聞き取りやすくなります。処理とアップロードは<strong>バックグラウンド</strong>で進むので（「⏳ 処理中…」と表示）、すぐ次の節を録音できます。",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>あなたの声を共有：</strong>🔗共有ボタンをタップすると、友だちがリンクを開いた時にあなたの声が聞こえます。録音がまだアップロード中なら、必ず聞こえるように完了を待ってから共有します。",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>一時停止／再開：</strong>音声録音の再生中に一時停止すると位置を保持し、再開すると最初からではなく<strong>止めた位置から続き</strong>を再生します。",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>削除：</strong>参照の下に「🎙️ この節にあなたの声」と表示されている場合、隣の「削除 ✕」をタップすると録音を消せます。以降は作者またはコンピューターの声に戻ります。",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>ヒント：</strong>再生画面上部中央の、日付やテーマ名を表示するボタンの下に <strong>【もっとテーマ聖句】</strong> があります。タップするとテーマ別セットが開き、すぐに切り替えられます。",
