    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "<strong>구절 세트를 들을</strong> 때, 한 구절을 읽는 자신의 목소리를 녹음할 수 있어요. 다음에 그 구절을 재생하면 컴퓨터 음성 대신 자신의 목소리가 들리고, 공유하면 친구도 당신의 목소리를 들을 수 있어요.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>목소리 녹음:</strong> (로그인 필요) 듣기 화면 하단 버튼 줄에서 🎙️ 마이크를 누르고 구절을 소리 내어 읽은 뒤 저장하세요.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>재생 우선순위:</strong> 당신의 목소리 ＞ 세트 저자의 목소리 ＞ 컴퓨터 음성(TTS). 한 번 녹음하면 항상 자신의 목소리가 들려요.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ 음성 보정:</strong> 녹음 후 \"음성 보정\"을 켜면 더 또렷해집니다. 처리와 업로드는 <strong>백그라운드</strong>에서 진행되므로(\"⏳ 처리 중…\" 표시) 바로 다음 구절을 녹음할 수 있어요.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>목소리 공유:</strong> 🔗 공유 버튼을 누르면 친구가 링크를 열 때 당신의 목소리가 들려요. 녹음이 아직 업로드 중이면 항상 들리도록 완료를 기다린 뒤 공유해요.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>일시정지 / 재개:</strong> 음성 녹음 재생 중 일시정지는 위치를 유지하고 재개는 처음이 아니라 <strong>멈춘 지점부터 이어서</strong> 재생해요.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>삭제:</strong> 참조 아래에 \"🎙️ 이 구절에 당신의 목소리\"가 보이면 옆의 \"삭제 ✕\"를 눌러 녹음을 지울 수 있어요. 이후에는 저자 또는 컴퓨터 음성으로 돌아갑니다.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>팁:</strong> 듣기 화면 상단 가운데, 날짜나 주제 이름이 표시된 버튼 아래에 <strong>【더 많은 주제 구절】</strong>이 있습니다. 누르면 주제별 세트가 열려 바로 바꿀 수 있습니다.",
