    "前往這個經文組": "ဤကျမ်းပိုဒ်အစုသို့ သွားရန်",
    "五、親聲朗讀 — 用你自己的聲音讀經": "၅။ ကိုယ့်အသံဖြင့် အသံထွက်ဖတ်ခြင်း",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "<strong>ကျမ်းပိုဒ်အစုကို နားထောင်</strong>နေစဉ် ကျမ်းပိုဒ်တစ်ခုကို ဖတ်သည့် ကိုယ့်အသံကို ဖမ်းနိုင်သည်။ နောက်တစ်ကြိမ် ထိုကျမ်းပိုဒ်ကို ဖွင့်လျှင် ကွန်ပျူတာအသံအစား ကိုယ့်အသံကို ကြားရမည် — မိတ်ဆွေများလည်း သင့်အသံကို ကြားရအောင် မျှဝေနိုင်သည်။",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>သင့်အသံ ဖမ်းရန်:</strong> (ဝင်ရောက်ရန်လို) နားထောင်စာမျက်နှာအောက်ရှိ ခလုတ်တန်းတွင် 🎙️ မိုက်ကို တို့ပြီး ကျမ်းပိုဒ်ကို အသံထွက်ဖတ်ကာ သိမ်းပါ။",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>ဖွင့်ရာ ဦးစားပေးအစီအစဉ်:</strong> သင့်အသံ ＞ အစုစာရေးသူ၏အသံ ＞ ကွန်ပျူတာအသံ (TTS)။ တစ်ကြိမ်ဖမ်းပြီးလျှင် အမြဲ ကိုယ့်အသံ ကြားရမည်။",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ အသံတိုးတက်စေရန်:</strong> ဖမ်းပြီးနောက် ပိုကြည်လင်စေရန် \"အသံတိုးတက်စေ\" ကို ဖွင့်နိုင်သည်။ လုပ်ဆောင်ခြင်းနှင့်တင်ခြင်းသည် <strong>နောက်ခံ၌</strong> ဆောင်ရွက်သည် (\"⏳ လုပ်ဆောင်နေသည်…\" ပြသ)၊ ထို့ကြောင့် နောက်ကျမ်းပိုဒ်ကို ချက်ချင်းဖမ်းနိုင်သည်။",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>သင့်အသံ မျှဝေရန်:</strong> 🔗 မျှဝေခလုတ်ကို တို့ပါ၊ မိတ်ဆွေက လင့်ခ်ဖွင့်လျှင် သင့်အသံ ကြားမည်။ အသံဖမ်းချက် တင်ဆဲဖြစ်လျှင် အမြဲကြားနိုင်ရန် ခလုတ်က ပြီးဆုံးအောင် စောင့်သည်။",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>ခဏရပ် / ဆက်လုပ်:</strong> အသံဖမ်းချက်ဖွင့်နေစဉ် ခဏရပ်က နေရာကို ထိန်းထားပြီး ဆက်လုပ်က အစမှမဟုတ်ဘဲ <strong>ရပ်ခဲ့သည့်နေရာမှ ဆက်</strong>ဖွင့်သည်။",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>ဖျက်ရန်:</strong> ရည်ညွှန်းချက်အောက်တွင် \"🎙️ ဤကျမ်းပိုဒ်တွင် သင့်အသံ\" ပြလျှင် ဘေးရှိ \"ဖျက် ✕\" ကို တို့ပြီး သင့်အသံဖမ်းချက်ကို ဖယ်နိုင်သည်; ထို့နောက် စာရေးသူ သို့မဟုတ် ကွန်ပျူတာအသံသို့ ပြန်သွားသည်။",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>အကြံပြုချက် -</strong> နားထောင်သည့်စခရင် အပေါ်အလယ်ရှိ (ရက်စွဲ သို့မဟုတ် အကြောင်းအရာအမည် ပြသော) ခလုတ်အောက်တွင် <strong>[နောက်ထပ် အကြောင်းအရာကျမ်းချက်များ]</strong> ဟု ရေးထားသည် — နှိပ်ပါက အကြောင်းအရာအစုများ ထပ်ပွင့်လာပြီး လျင်မြန်စွာ ပြောင်းနိုင်သည်။",
