    "目前 App 版本不支援掃描，請在 Safari 開 verserain.com 掃描，或在下方手動貼上推薦碼。下次 App 更新後會自動可用。": "Phiên bản ứng dụng này chưa hỗ trợ quét. Hãy mở verserain.com trong Safari để quét, hoặc dán mã bên dưới. Sẽ hoạt động sau lần cập nhật ứng dụng tới.",
