    "這是視障友善版。現在選擇的是 {title}，本次 {n} 節經文。按開始後，系統會先讀經文出處，停頓兩秒，再等你開口背誦。若一段時間沒有答對，系統會朗讀提示。遊戲中按 Escape 可以離開。": "Đây là chế độ trợ năng. Bộ đã chọn là {title}, {n} câu. Sau khi bắt đầu, ứng dụng đọc tham chiếu, dừng hai giây, rồi chờ bạn đọc thuộc. Nếu cần trợ giúp, ứng dụng sẽ đọc gợi ý. Nhấn Escape khi chơi để thoát.",
