    "測試版會用主要語言朗讀經文，並在每個方塊下方顯示第二語言。第二行目前是短句估算對齊，適合先測試閱讀感。": "Bản beta này đọc ngôn ngữ chính và hiển thị ngôn ngữ thứ hai dưới mỗi ô. Dòng thứ hai dùng căn chỉnh cụm từ ước lượng để thử trải nghiệm đọc trước.",
