    "這節之前是用別的帳號錄的,無法覆蓋。請先刪掉這一行再重加,或用原本的帳號登入。": "Câu này được ghi bằng tài khoản khác nên không thể ghi đè. Hãy xóa và thêm lại dòng này, hoặc đăng nhập bằng tài khoản gốc.",
