    "今日的經文雨活動已累積 {n} 分": "Hôm nay bạn đã tích {n} điểm trong hoạt động VerseRain",
    "連續 {n} 天": "Chuỗi {n} ngày",
    "今天開始建立連續紀錄吧！": "Bắt đầu chuỗi của bạn hôm nay!",
    "最長連續：{n} 天": "Kỷ lục: {n} ngày",
    "個人累積": "Tích lũy",
    "已挑戰": "Lượt chơi",
    "已栽種": "Cây",
    "結果子": "Đã kết trái",
    "前往這個經文組": "Đến bộ câu này",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Đọc thành tiếng bằng giọng của bạn",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Khi <strong>nghe một bộ câu</strong>, bạn có thể ghi giọng mình đọc một câu. Lần sau phát câu đó, bạn sẽ nghe chính mình thay vì giọng máy tính — và có thể chia sẻ để bạn bè cũng nghe giọng bạn.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Ghi giọng của bạn:</strong> (cần đăng nhập) Trong hàng nút ở dưới màn hình nghe, chạm 🎙️ micro, đọc to câu và lưu.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Thứ tự ưu tiên phát:</strong> giọng bạn ＞ giọng tác giả bộ ＞ giọng máy tính (TTS). Một khi đã ghi, bạn luôn nghe chính mình.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Làm rõ giọng:</strong> Sau khi ghi, bạn có thể bật \"Làm rõ giọng\" cho rõ hơn. Xử lý và tải lên chạy <strong>ở nền</strong> (hiển thị \"⏳ Đang xử lý…\"), nên bạn có thể ghi câu tiếp theo ngay.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Chia sẻ giọng của bạn:</strong> Chạm nút 🔗 chia sẻ và bạn bè sẽ nghe giọng bạn khi mở liên kết. Nếu bản ghi còn đang tải lên, nút sẽ chờ tải xong để họ luôn nghe được.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Tạm dừng / Tiếp tục:</strong> Khi phát bản ghi giọng, Tạm dừng giữ vị trí và Tiếp tục <strong>chạy tiếp từ chỗ dừng</strong> thay vì bắt đầu lại.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Xóa:</strong> Nếu dưới tham chiếu hiện \"🎙️ Giọng của bạn ở câu này\", chạm \"Xóa ✕\" bên cạnh để gỡ bản ghi; phát lại sẽ quay về giọng tác giả hoặc máy tính.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Mẹo:</strong> Nút ở giữa phía trên màn hình nghe (hiển thị ngày hoặc tên chủ đề) có dòng <strong>[Thêm câu theo chủ đề]</strong> bên dưới — chạm để mở thêm bộ câu chủ đề và chuyển nhanh.",
    "多人遊戲進行中": "Nhiều người chơi Đang diễn ra",
    "多人遊戲結束！": "Nhiều người chơi Hoàn tất!",
    "(難度 {n})": "(Cấp {n})",
