    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Saat <strong>mendengarkan set ayat</strong>, kamu bisa merekam suaramu membaca sebuah ayat. Lain kali memutarnya, kamu mendengar dirimu, bukan suara komputer — dan bisa dibagikan agar teman juga mendengar suaramu.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Rekam suaramu:</strong> (perlu masuk) Pada deretan tombol di bawah layar dengar, ketuk 🎙️ mikrofon, baca ayat nyaring, lalu simpan.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Prioritas pemutaran:</strong> suaramu ＞ suara penulis set ＞ suara komputer (TTS). Setelah merekam, kamu selalu mendengar dirimu.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Sempurnakan suara:</strong> Setelah merekam, kamu bisa mengaktifkan \"Sempurnakan suara\" agar lebih jernih. Pemrosesan dan unggah berjalan <strong>di latar belakang</strong> (tampil \"⏳ Memproses…\"), jadi kamu bisa langsung merekam ayat berikutnya.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Bagikan suaramu:</strong> Ketuk tombol 🔗 bagikan dan temanmu mendengar suaramu saat membuka tautan. Jika rekaman masih diunggah, tombol menunggu selesai agar ia selalu mendengarnya.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Jeda / Lanjut:</strong> Saat rekaman suara diputar, Jeda menahan posisi dan Lanjut <strong>melanjutkan dari tempat berhenti</strong>, bukan mengulang.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Hapus:</strong> Jika di bawah referensi tertulis \"🎙️ Suaramu pada ayat ini\", ketuk \"Hapus ✕\" di sampingnya untuk menghapus rekamanmu; pemutaran lalu kembali ke suara penulis atau komputer.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Tips:</strong> Tombol di tengah atas layar dengar (menampilkan tanggal atau nama topik) di bawahnya tertulis <strong>[Lebih banyak ayat tema]</strong> — ketuk untuk membuka lebih banyak set ayat tema dan beralih cepat.",
