    "今日問候": "Ucapan Hari Ini",
    "{name}，今日的經文雨活動已累積 {n} 分": "{name}, hari ini anda kumpul {n} mata dalam aktiviti VerseRain",
    "今日的經文雨活動已累積 {n} 分": "Hari ini anda kumpul {n} mata dalam aktiviti VerseRain",
    "連續 {n} 天": "Rentetan {n} hari",
    "今天開始建立連續紀錄吧！": "Mula rentetan anda hari ini!",
    "最長連續：{n} 天": "Terbaik: {n} hari",
    "個人累積": "Kumulatif",
    "已挑戰": "Main",
    "已栽種": "Pokok",
    "結果子": "Berbuah",
    "前往這個經文組": "Pergi ke set ayat ini",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Baca Kuat dengan Suara Sendiri",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Semasa <strong>mendengar set ayat</strong>, anda boleh merakam suara sendiri membaca sesuatu ayat. Kali seterusnya memainkannya, anda mendengar diri sendiri, bukan suara komputer — dan boleh dikongsi supaya rakan turut mendengar suara anda.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Rakam suara anda:</strong> (perlu log masuk) Pada deretan butang di bawah skrin dengar, ketik 🎙️ mikrofon, baca ayat dengan kuat, kemudian simpan.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Keutamaan main:</strong> suara anda ＞ suara penulis set ＞ suara komputer (TTS). Setelah merakam, anda sentiasa mendengar diri sendiri.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Tambah baik suara:</strong> Selepas merakam, anda boleh hidupkan \"Tambah baik suara\" untuk kejelasan. Pemprosesan dan muat naik berjalan <strong>di latar</strong> (dipaparkan \"⏳ Memproses…\"), jadi anda boleh terus merakam ayat seterusnya.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Kongsi suara anda:</strong> Ketik butang 🔗 kongsi dan rakan anda mendengar suara anda apabila membuka pautan. Jika rakaman masih dimuat naik, butang menunggu ia selesai supaya dia sentiasa mendengarnya.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Jeda / Sambung:</strong> Semasa rakaman suara dimainkan, Jeda menahan kedudukan dan Sambung <strong>meneruskan dari tempat berhenti</strong>, bukan bermula semula.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Padam:</strong> Jika di bawah rujukan tertera \"🎙️ Suara anda pada ayat ini\", ketik \"Padam ✕\" di sebelahnya untuk mengeluarkan rakaman anda; mainan kemudian kembali ke suara penulis atau komputer.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Petua:</strong> Butang di tengah atas skrin dengar (memaparkan tarikh atau nama topik) di bawahnya tertulis <strong>[Lagi ayat tema]</strong> — ketik untuk membuka lebih banyak set ayat tema dan bertukar pantas.",
