    "今天開始建立連續紀錄吧！": "Comece sua sequência hoje!",
    "最長連續：{n} 天": "Melhor: {n} dias",
    "個人累積": "Acumulado",
    "已挑戰": "Partidas",
    "已栽種": "Árvores",
    "結果子": "Frutificou",
    "前往這個經文組": "Ir para este conjunto de versículos",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Leia em voz alta com sua própria voz",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Enquanto <strong>ouve um conjunto de versículos</strong>, você pode gravar sua própria voz lendo um versículo. Da próxima vez que reproduzi-lo, ouvirá você mesmo em vez da voz do computador — e pode compartilhá-lo para que amigos também ouçam sua voz.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Grave sua voz:</strong> (requer login) Na fileira de botões no rodapé da tela de escuta, toque no 🎙️ microfone, leia o versículo em voz alta e salve.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Prioridade de reprodução:</strong> sua voz ＞ a voz do autor do conjunto ＞ voz do computador (TTS). Depois de gravar, você sempre ouvirá a si mesmo.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Aprimorar voz:</strong> Após gravar, você pode ativar \"Aprimorar voz\" para mais clareza. O processamento e o envio ocorrem <strong>em segundo plano</strong> (mostrado como \"⏳ Processando…\"), então você pode gravar o próximo versículo já.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Compartilhe sua voz:</strong> Toque no botão 🔗 compartilhar e seu amigo ouvirá sua voz ao abrir o link. Se a gravação ainda estiver enviando, o botão espera terminar para que ele sempre a ouça.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Pausar / Retomar:</strong> Ao reproduzir uma gravação de voz, Pausar mantém a posição e Retomar <strong>continua de onde parou</strong> em vez de recomeçar.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Excluir:</strong> Se aparecer \"🎙️ Sua voz neste versículo\" sob a referência, toque em \"Excluir ✕\" ao lado para remover sua gravação; a reprodução volta então à voz do autor ou do computador.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Dica:</strong> O botão no centro superior da tela de escuta (mostrando a data ou o nome do tema) tem embaixo <strong>[Mais versículos temáticos]</strong> — toque nele para abrir mais conjuntos temáticos e trocar rápido.",
