    "{name}，今日的經文雨活動已累積 {n} 分": "{name}, vous avez cumulé {n} points aujourd’hui dans l’activité VerseRain",
    "今日的經文雨活動已累積 {n} 分": "Vous avez cumulé {n} points aujourd’hui dans l’activité VerseRain",
    "連續 {n} 天": "Série de {n} jours",
    "今天開始建立連續紀錄吧！": "Commencez votre série aujourd’hui !",
    "最長連續：{n} 天": "Record : {n} jours",
    "個人累積": "Cumulé",
    "已挑戰": "Parties",
    "已栽種": "Arbres",
    "結果子": "A porté du fruit",
    "前往這個經文組": "Aller à cet ensemble de versets",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Lisez à voix haute avec votre propre voix",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Pendant l’<strong>écoute d’un ensemble de versets</strong>, vous pouvez enregistrer votre propre voix lisant un verset. La prochaine fois, vous vous entendrez au lieu de la voix de l’ordinateur — et vous pouvez le partager pour que vos amis entendent aussi votre voix.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Enregistrez votre voix :</strong> (connexion requise) Dans la rangée de boutons en bas de l’écran d’écoute, touchez le 🎙️ micro, lisez le verset à voix haute et enregistrez.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Priorité de lecture :</strong> votre voix ＞ la voix de l’auteur de l’ensemble ＞ voix de l’ordinateur (TTS). Une fois enregistrée, vous vous entendrez toujours.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Améliorer la voix :</strong> Après l’enregistrement, vous pouvez activer « Améliorer la voix » pour plus de clarté. Le traitement et l’envoi se font <strong>en arrière-plan</strong> (affiché « ⏳ Traitement… »), vous pouvez donc enregistrer le verset suivant tout de suite.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Partagez votre voix :</strong> Touchez le bouton 🔗 partager et votre ami entendra votre voix en ouvrant le lien. Si l’enregistrement est encore en cours d’envoi, le bouton attend la fin pour qu’il l’entende toujours.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Pause / Reprendre :</strong> Lors de la lecture d’un enregistrement vocal, Pause maintient la position et Reprendre <strong>continue là où il s’est arrêté</strong> au lieu de recommencer.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Supprimer :</strong> Si « 🎙️ Votre voix sur ce verset » s’affiche sous la référence, touchez « Supprimer ✕ » à côté pour retirer votre enregistrement ; la lecture revient alors à la voix de l’auteur ou de l’ordinateur.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Astuce :</strong> Le bouton en haut au centre de l’écran d’écoute (montrant la date ou le nom du thème) a en dessous <strong>[Plus de versets thématiques]</strong> — touchez-le pour ouvrir plus d’ensembles thématiques et changer rapidement.",
