    "這是視障友善版。現在選擇的是 {title}，本次 {n} 節經文。按開始後，系統會先讀經文出處，停頓兩秒，再等你開口背誦。若一段時間沒有答對，系統會朗讀提示。遊戲中按 Escape 可以離開。": "Это доступный режим. Выбран набор {title}, {n} стихов. После запуска приложение прочитает ссылку, сделает паузу в две секунды и будет ждать вашего чтения наизусть. Если нужна помощь, приложение прочитает подсказку. Нажмите Escape во время игры, чтобы выйти.",
