    "今日的經文雨活動已累積 {n} 分": "Сегодня вы набрали {n} очков в активности VerseRain",
    "連續 {n} 天": "Серия {n} дней",
    "今天開始建立連續紀錄吧！": "Начните свою серию сегодня!",
    "最長連續：{n} 天": "Рекорд: {n} дней",
    "個人累積": "Всего",
    "已挑戰": "Игры",
    "已栽種": "Деревья",
    "結果子": "Принесло плод",
    "前往這個經文組": "Перейти к этому набору стихов",
    "五、親聲朗讀 — 用你自己的聲音讀經": "5. Читайте вслух своим голосом",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "Во время <strong>прослушивания набора стихов</strong> вы можете записать свой голос, читая стих. В следующий раз вы услышите себя вместо компьютерного голоса — и можете поделиться, чтобы друзья тоже услышали ваш голос.",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>Запишите свой голос:</strong> (нужен вход) В ряду кнопок внизу экрана прослушивания нажмите 🎙️ микрофон, прочитайте стих вслух и сохраните.",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>Приоритет воспроизведения:</strong> ваш голос ＞ голос автора набора ＞ компьютерный голос (TTS). Записав, вы всегда будете слышать себя.",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ Улучшить голос:</strong> После записи можно включить «Улучшить голос» для чёткости. Обработка и загрузка идут <strong>в фоне</strong> (показано «⏳ Обработка…»), так что можно сразу записывать следующий стих.",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>Поделитесь голосом:</strong> Нажмите кнопку 🔗 поделиться, и ваш друг услышит ваш голос, открыв ссылку. Если запись ещё загружается, кнопка дождётся завершения, чтобы он всегда её услышал.",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>Пауза / Продолжить:</strong> При воспроизведении голосовой записи Пауза удерживает позицию, а Продолжить <strong>возобновляет с места остановки</strong>, а не с начала.",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>Удаление:</strong> Если под ссылкой показано «🎙️ Ваш голос на этом стихе», нажмите рядом «Удалить ✕», чтобы убрать вашу запись; воспроизведение вернётся к голосу автора или компьютера.",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>Совет:</strong> У кнопки вверху по центру экрана прослушивания (показывает дату или название темы) снизу есть <strong>[Больше тематических стихов]</strong> — нажмите, чтобы открыть больше тематических наборов и быстро переключаться.",
