    "五、親聲朗讀 — 用你自己的聲音讀經": "5. अपनी आवाज़ में ज़ोर से पढ़ें",
    "在<strong>聆聽經文組</strong>時，你可以錄下自己的聲音來讀某一節。之後再聽這一節，聽到的就是你自己的聲音，而不是電腦語音；還能把它分享給朋友，讓他們也聽見你的親聲。": "<strong>किसी वचन समूह को सुनते</strong> समय, आप किसी वचन को पढ़ते हुए अपनी आवाज़ रिकॉर्ड कर सकते हैं। अगली बार उस वचन को चलाने पर आप कंप्यूटर आवाज़ के बजाय स्वयं को सुनेंगे — और इसे साझा कर सकते हैं ताकि दोस्त भी आपकी आवाज़ सुनें।",
    "<strong>錄下你的親聲：</strong>（需先登入）聆聽畫面下方那排按鈕中有一顆 🎙️ 麥克風鍵，點它、照著經文唸一遍、儲存即可。": "<strong>अपनी आवाज़ रिकॉर्ड करें:</strong> (लॉगिन आवश्यक) सुनने की स्क्रीन के नीचे बटनों की पंक्ति में 🎙️ माइक पर स्पर्श करें, वचन ज़ोर से पढ़ें और सहेजें।",
    "<strong>播放優先順序：</strong>你的親聲 ＞ 經文組作者的親聲 ＞ 電腦語音（TTS）。只要你錄了，聽到的一定是你自己的聲音。": "<strong>प्लेबैक प्राथमिकता:</strong> आपकी आवाज़ ＞ समूह लेखक की आवाज़ ＞ कंप्यूटर आवाज़ (TTS)। एक बार रिकॉर्ड करने पर, आप हमेशा स्वयं को सुनेंगे।",
    "<strong>✨ 美化人聲：</strong>錄完可勾選「美化人聲」讓聲音更清晰。處理與上傳會在<strong>背景進行</strong>（畫面顯示「⏳ 親聲處理中…」），你可以馬上去錄下一節，不必等它跑完。": "<strong>✨ आवाज़ सुधारें:</strong> रिकॉर्ड के बाद आप स्पष्टता के लिए \"आवाज़ सुधारें\" चालू कर सकते हैं। प्रसंस्करण और अपलोड <strong>पृष्ठभूमि में</strong> होते हैं (\"⏳ संसाधित हो रहा है…\" दिखता है), तो आप तुरंत अगला वचन रिकॉर्ड कर सकते हैं।",
    "<strong>分享給朋友聽你的聲音：</strong>點 🔗 分享鍵，朋友打開連結就會聽到你的親聲。若錄音還在上傳，分享鍵會先等上傳完成再產生連結，確保對方一定聽得到。": "<strong>अपनी आवाज़ साझा करें:</strong> 🔗 साझा बटन स्पर्श करें और लिंक खोलने पर आपका दोस्त आपकी आवाज़ सुनेगा। यदि रिकॉर्डिंग अभी अपलोड हो रही है, तो बटन उसके पूरा होने तक प्रतीक्षा करता है ताकि वह हमेशा सुन सके।",
    "<strong>暫停 / 繼續：</strong>播放親聲錄音時按暫停會停在原處，再按繼續會<strong>從原處接著播</strong>，不會從頭重讀。": "<strong>रोकें / जारी रखें:</strong> आवाज़ रिकॉर्डिंग चलते समय रोकें स्थिति बनाए रखता है और जारी रखें <strong>वहीं से आगे बढ़ता है जहाँ रुका था</strong>, फिर से शुरू नहीं होता।",
    "<strong>刪除：</strong>經文出處下方若顯示「🎙️ 這節有你的親聲」，點旁邊的「刪除 ✕」即可移除你的錄音，之後會回到作者的親聲或電腦語音。": "<strong>हटाएँ:</strong> यदि संदर्भ के नीचे \"🎙️ इस वचन पर आपकी आवाज़\" दिखे, तो उसके बगल में \"हटाएँ ✕\" स्पर्श करें; फिर प्लेबैक लेखक या कंप्यूटर आवाज़ पर लौट आता है।",
    "<strong>小提示：</strong>聆聽畫面上方中間、顯示日期或主題名稱的按鈕，下面寫著 <strong>【更多的主題經文】</strong> —— 點一下就能展開更多主題經文組，快速切換聆聽不同主題。": "<strong>सुझाव:</strong> सुनने की स्क्रीन के ऊपर बीच वाले बटन (तारीख़ या विषय नाम दिखाता) के नीचे <strong>[और विषय वचन]</strong> लिखा है — इसे स्पर्श करके और विषय वचन समूह खोलें और तेज़ी से बदलें।",
