    "註冊成功！請至您的信箱查看驗證碼。": "पंजीकरण सफल! सत्यापन कोड के लिए अपना ईमेल देखें।",
    "重設密碼的連結已寄到您的信箱，30 分鐘內有效。": "पासवर्ड रीसेट लिंक आपके ईमेल पर भेजा गया है। यह 30 मिनट तक मान्य है।",
