    "此瀏覽器不支援推播。請用桌面 Chrome / Edge / Firefox 或 Android Chrome 來啟用。": "यह ब्राउज़र पुश का समर्थन नहीं करता। डेस्कटॉप Chrome / Edge / Firefox या Android Chrome उपयोग करें।",
