    "瀏覽器已封鎖通知。請到網站設定 → 通知 → 允許，再回來重試。": "ब्राउज़र ने सूचनाएँ अवरुद्ध कर दी हैं। साइट सेटिंग्स में अनुमति दें और पुनः प्रयास करें।",
    "開啟後，每天上午 7 點（你的時區）會收到當日 dailyverses.net 經文推播，點通知一鍵進入「聆聽」。": "चालू करने पर, हर सुबह 7 बजे (आपका समय क्षेत्र) आपको dailyverses.net से दिन के वचन का पुश मिलेगा। सुनने के लिए स्पर्श करें।",
